-- ============================================================================
-- REFRESH MEMOS — self-referencing lookups (see 02-create-functions.sql)
-- Generated by rulebook-to-postgres tool. Runs after the seed data. Each round
-- memoises the rows whose self-referenced parents are already memoised, so every
-- __compute call reads its parents from the memo. Rows on a genuine row cycle are
-- never ready and stay unmemoised (their wrapper falls back to __compute).
-- ============================================================================

CREATE OR REPLACE FUNCTION erb_refresh_memo_rulebook_releases() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_rulebook_releases_cq_coverage_percent;
  DELETE FROM erb_memo_rulebook_releases_cq_run_count;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.rulebook_release_id::text FROM rulebook_releases c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_rulebook_releases_cq_run_count m WHERE m.id = c.rulebook_release_id::text)
      AND (c.previous_release IS NULL OR NOT EXISTS (SELECT 1 FROM rulebook_releases p WHERE p.rulebook_release_id = c.previous_release) OR EXISTS (SELECT 1 FROM erb_memo_rulebook_releases_cq_run_count m WHERE m.id = c.previous_release::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_rulebook_releases_cq_coverage_percent(id, val) SELECT c.rulebook_release_id::text, calc_rulebook_releases_cq_coverage_percent__compute(c.rulebook_release_id) FROM rulebook_releases c JOIN erb_memo_round r ON r.id = c.rulebook_release_id::text;
    INSERT INTO erb_memo_rulebook_releases_cq_run_count(id, val) SELECT c.rulebook_release_id::text, calc_rulebook_releases_cq_run_count__compute(c.rulebook_release_id) FROM rulebook_releases c JOIN erb_memo_round r ON r.id = c.rulebook_release_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_role_assignments() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_role_assignments_agent_kind;
  DELETE FROM erb_memo_role_assignments_override_rate_percent;
  DELETE FROM erb_memo_role_assignments_decision_count;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.role_assignment_id::text FROM role_assignments c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_role_assignments_decision_count m WHERE m.id = c.role_assignment_id::text)
      AND (c.supersedes_assignment IS NULL OR NOT EXISTS (SELECT 1 FROM role_assignments p WHERE p.role_assignment_id = c.supersedes_assignment) OR EXISTS (SELECT 1 FROM erb_memo_role_assignments_decision_count m WHERE m.id = c.supersedes_assignment::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_role_assignments_agent_kind(id, val) SELECT c.role_assignment_id::text, calc_role_assignments_agent_kind__compute(c.role_assignment_id) FROM role_assignments c JOIN erb_memo_round r ON r.id = c.role_assignment_id::text;
    INSERT INTO erb_memo_role_assignments_override_rate_percent(id, val) SELECT c.role_assignment_id::text, calc_role_assignments_override_rate_percent__compute(c.role_assignment_id) FROM role_assignments c JOIN erb_memo_round r ON r.id = c.role_assignment_id::text;
    INSERT INTO erb_memo_role_assignments_decision_count(id, val) SELECT c.role_assignment_id::text, calc_role_assignments_decision_count__compute(c.role_assignment_id) FROM role_assignments c JOIN erb_memo_round r ON r.id = c.role_assignment_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_procedure_types() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_procedure_types_is_detached_from_taxonomy;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.procedure_type_id::text FROM procedure_types c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_procedure_types_is_detached_from_taxonomy m WHERE m.id = c.procedure_type_id::text)
      AND (c.broader_procedure_type IS NULL OR NOT EXISTS (SELECT 1 FROM procedure_types p WHERE p.procedure_type_id = c.broader_procedure_type) OR EXISTS (SELECT 1 FROM erb_memo_procedure_types_is_detached_from_taxonomy m WHERE m.id = c.broader_procedure_type::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_procedure_types_is_detached_from_taxonomy(id, val) SELECT c.procedure_type_id::text, calc_procedure_types_is_detached_from_taxonomy__compute(c.procedure_type_id) FROM procedure_types c JOIN erb_memo_round r ON r.id = c.procedure_type_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_send_intents() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_send_intents_is_cleared_to_send;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.send_intent_id::text FROM send_intents c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_send_intents_is_cleared_to_send m WHERE m.id = c.send_intent_id::text)
      AND (c.alternate_channel_intent IS NULL OR NOT EXISTS (SELECT 1 FROM send_intents p WHERE p.send_intent_id = c.alternate_channel_intent) OR EXISTS (SELECT 1 FROM erb_memo_send_intents_is_cleared_to_send m WHERE m.id = c.alternate_channel_intent::text))
      AND (c.retry_intent IS NULL OR NOT EXISTS (SELECT 1 FROM send_intents p WHERE p.send_intent_id = c.retry_intent) OR EXISTS (SELECT 1 FROM erb_memo_send_intents_is_cleared_to_send m WHERE m.id = c.retry_intent::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_send_intents_is_cleared_to_send(id, val) SELECT c.send_intent_id::text, calc_send_intents_is_cleared_to_send__compute(c.send_intent_id) FROM send_intents c JOIN erb_memo_round r ON r.id = c.send_intent_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_ai_adoption_initiatives() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_ai_adoption_initiatives_reviewed_output_count;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.ai_adoption_initiative_id::text FROM ai_adoption_initiatives c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_ai_adoption_initiatives_reviewed_output_count m WHERE m.id = c.ai_adoption_initiative_id::text)
      AND (c.preceding_initiative IS NULL OR NOT EXISTS (SELECT 1 FROM ai_adoption_initiatives p WHERE p.ai_adoption_initiative_id = c.preceding_initiative) OR EXISTS (SELECT 1 FROM erb_memo_ai_adoption_initiatives_reviewed_output_count m WHERE m.id = c.preceding_initiative::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_ai_adoption_initiatives_reviewed_output_count(id, val) SELECT c.ai_adoption_initiative_id::text, calc_ai_adoption_initiatives_reviewed_output_count__compute(c.ai_adoption_initiative_id) FROM ai_adoption_initiatives c JOIN erb_memo_round r ON r.id = c.ai_adoption_initiative_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_problem_occurrences() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_problem_occurrences_is_solved;
  DELETE FROM erb_memo_problem_occurrences_solver_is_still_engaged;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.problem_occurrence_id::text FROM problem_occurrences c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_problem_occurrences_solver_is_still_engaged m WHERE m.id = c.problem_occurrence_id::text)
      AND (c.prior_occurrence IS NULL OR NOT EXISTS (SELECT 1 FROM problem_occurrences p WHERE p.problem_occurrence_id = c.prior_occurrence) OR EXISTS (SELECT 1 FROM erb_memo_problem_occurrences_solver_is_still_engaged m WHERE m.id = c.prior_occurrence::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_problem_occurrences_is_solved(id, val) SELECT c.problem_occurrence_id::text, calc_problem_occurrences_is_solved__compute(c.problem_occurrence_id) FROM problem_occurrences c JOIN erb_memo_round r ON r.id = c.problem_occurrence_id::text;
    INSERT INTO erb_memo_problem_occurrences_solver_is_still_engaged(id, val) SELECT c.problem_occurrence_id::text, calc_problem_occurrences_solver_is_still_engaged__compute(c.problem_occurrence_id) FROM problem_occurrences c JOIN erb_memo_round r ON r.id = c.problem_occurrence_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memos() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM erb_refresh_memo_rulebook_releases();
  PERFORM erb_refresh_memo_role_assignments();
  PERFORM erb_refresh_memo_procedure_types();
  PERFORM erb_refresh_memo_send_intents();
  PERFORM erb_refresh_memo_ai_adoption_initiatives();
  PERFORM erb_refresh_memo_problem_occurrences();
END $$;

SELECT erb_refresh_memos();
